import Badge from "../ui/Badge";
import Button from "../ui/Button";

export default function Hero() {
    return (
        <section className="py-16 md:py-32 relative overflow-hidden">
            {/* Background code snippets */}
            <div className="absolute inset-0 pointer-events-none opacity-15">
                {/* Top snippet */}
                <div className="absolute top-5 -right-20 max-w-70 text-[0.4rem] leading-6 text-[var(--muted-foreground)] font-mono whitespace-pre transform -rotate-2">
                    <div className="p-5 rounded-md bg-[var(--input)] border border-[var(--border)]">
                        from fastapi import FastAPI from pydantic import BaseModel app = FastAPI(title="orders")
                    </div>
                </div>

                {/* Bottom snippet */}
                <div className="absolute bottom-5 -left-10 max-w-70 text-[0.4rem] leading-6 text-[var(--muted-foreground)] font-mono whitespace-pre transform rotate-1">
                    <div className="p-4 rounded-md bg-[var(--background)] border border-dashed border-[var(--border)]">
                        $ psql postgresql://localhost/app &gt; \dt &gt; SELECT COUNT(*) FROM orders;
                    </div>
                </div>
            </div>

            <div className="container mx-auto px-5">
                <div className="relative z-10">
                    <Badge>Available for new opportunities</Badge>
                    <h1 className="mt-5 text-3xl md:text-4xl font-medium leading-tight text-[var(--foreground)]">
                        Systems that stay up.<br />Quietly powering products.
                    </h1>
                    <p className="mt-5 text-base md:text-lg text-[var(--muted-foreground)] leading-6">
                        I'm Vincent Odume, a backend-leaning software engineer focused on reliable APIs, pragmatic architecture, and turning complex systems into calm, maintainable code.
                    </p>
                    <div className="mt-10 flex flex-col gap-3">
                        <Button variant="primary" className="w-full">View Projects</Button>
                        <Button variant="outline" className="w-full">View Blog Posts</Button>
                    </div>
                </div>
            </div>
        </section>
    );
}
